sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.qr-container {
    max-width: 900px;
    margin: 40px auto;
    text-align: center;
}

.qr-container h1 {
    font-size: 32px;
    margin-bottom: 30px;
}

.qr-card {
    background: white;
    padding: 35px;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(0,0,0,0.15);
}

.qr-card h2 {
    font-size: 26px;
    margin-bottom: 5px;
}

.subtitle {
    color: #666;
    margin-bottom: 25px;
}

.qr-box {
    margin: 20px auto;
    padding: 20px;
    width: 290px;
    background: white;
    border: 1px solid #ddd;
}

.qr-box img {
    width: 250px;
    height: 250px;
}

.details {
    max-width: 600px;
    margin: 25px auto;
    text-align: left;
}

.details div {
    display: flex;
    justify-content: space-between;
    padding: 10px;
    border-bottom: 1px solid #eee;
}

.status {
    margin-top: 20px;
    padding: 12px;
    background: #e8f5e9;
    border-radius: 6px;
}

.instruction {
    margin-top: 20px;
    font-size: 17px;
    font-weight: 500;
}

.error {
    background: #ffebee;
    padding: 30px;
    border-radius: 10px;
    color: #c62828;
}

sp_widget.script:
(function() {

    data.found = false;

    var interviewId = options.interview_id;

    if (!interviewId) {
        interviewId = $sp.getParameter("interview_id");
    }

    if (!interviewId) {
        data.message = "Interview ID is missing.";
        return;
    }

    var gr = new GlideRecord("x_snc_campus360_mock_interview");

    /*
     * First try Interview ID.
     */
    gr.addQuery("interview_id", interviewId);
    gr.query();

    /*
     * If no record is found, try Sys ID.
     * This makes the page more robust.
     */
    if (!gr.next()) {

        gr = new GlideRecord("x_snc_campus360_mock_interview");

        if (gr.get(interviewId)) {
            // Record found using Sys ID
        } else {
            data.message = "No Mock Interview record found for: " + interviewId;
            return;
        }
    }

    data.found = true;

    data.interview_id = gr.getValue("interview_id");

    data.student = gr.student.getDisplayValue();

    data.trainer = gr.trainer.getDisplayValue();

    data.interview_type = gr.getDisplayValue("interview_type");

    data.interview_date = gr.getDisplayValue("interview_date");

    data.start_time = gr.getDisplayValue("start_time");

    data.end_time = gr.getDisplayValue("end_time");

    data.qr_status = gr.getDisplayValue("qr_status");

    /*
     * URL that the student's phone will open.
     */
    var attendanceURL =
        gs.getProperty("glide.servlet.uri") +
        "sp?id=qr_attendance&interview_id=" +
        encodeURIComponent(gr.getValue("interview_id"));

    /*
     * QR image generated from the attendance URL.
     */
    data.qr_url =
        "https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=" +
        encodeURIComponent(attendanceURL);

})();
